def solve(grid):
    """Count the number of islands (connected components of 1s) in a binary grid.
    Connectivity is 4-directional (up, down, left, right).
    Args:
        grid: List[List[int]] where each element is 0 or 1.
    Returns:
        Integer count of islands.
    """
    if not grid:
        return 0
    n = len(grid)
    m = len(grid[0]) if n else 0
