def solve(grid):
    """Count the number of islands (connected components of 1s) in a binary grid.
    4-directional connectivity.
    """
    if not grid:
        return 0
    n = len(grid)
    m = len(grid[0])
    visited = [[False]*m for _ in range(n)]
    def dfs(r,c):
        stack = [(r,c)]
        while stack:
            i,j = stack.pop()
