def solve(nums):
    """Return length of longest strictly increasing subsequence using O(n log n) patience sorting."""
    import bisect
    piles = []
    for x in nums:
        i = bisect.bisect_left(piles, x)
        if i == len(piles):
            piles.append(x)
        else:
            piles[i] = x
    return len(piles)

